// The page list is free. Keep the pages worth rebuilding: every unique page
// plus one example of each template (blog post, product, doc...), or the
// pages you listed yourself in Set Website and Output.
const scan = $input.first().json
const settings = $('Set Website and Output').first().json
if (scan.premium) {
  throw new Error(scan.premium.reason + ' Plans: ' + scan.premium.upgradeUrl)
}
const max = Math.max(1, Number(settings.maxPages) || 10)
const own = String(settings.pages || '').split(/[\s,]+/).filter(u => /^https?:\/\//.test(u))
const urls = own.length ? own : (scan.suggested || []).map(p => typeof p === 'string' ? p : p.url)
if (!urls.length) throw new Error('No pages found on ' + settings.website + '. Put the addresses in "pages" in Set Website and Output.')
return [...new Set(urls)].slice(0, max).map(url => ({ json: { url, output: settings.output }, pairedItem: { item: 0 } }))

// One folder per page, one file per section, in page order.
const output = $('Set Website and Output').first().json.output
const ext = { tailwind: 'html', html: 'html', jsx: 'jsx', vue: 'vue', elementor: 'json', shopify: 'liquid' }[output] || 'txt'
const slug = s => String(s || '').toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '').slice(0, 40)
const picked = $('Pick the Pages').all().map(i => i.json.url)
const firstRun = $('Extract Each Page as Code').all().map(i => i.json)
const binary = {}
const pages = []
const failed = []
let n = 0
$input.all().forEach((item, i) => {
  const r = item.json
  const url = r.url || picked[i]
  if (!r.sections || !r.sections.length) {
    // A page that failed in the first call keeps that call's error.
    const first = (firstRun[i] || {}).error
    const e = first || r.error
    failed.push({ url, error: (e && (e.message || e)) || 'No sections returned' })
    return
  }
  const path = String(url).split('/').slice(3).join('/').split(/[?#]/)[0]
  const folder = slug(path) || 'home'
  r.sections.forEach((s, j) => {
    const name = String(j + 1).padStart(2, '0') + '-' + (slug(String(s.label || '').split(/\s+/).slice(0, 4).join(' ')) || 'section')
    const text = s.css && ext === 'html' ? '<style>\n' + s.css + '\n</style>\n' + s.code : s.code
    binary['file_' + (n++)] = { data: Buffer.from(String(text)).toString('base64'), mimeType: 'text/plain', fileName: folder + '/' + name + '.' + ext, fileExtension: ext }
  })
  pages.push({ url, folder, sections: r.sections.length, complete: r.complete !== false, pagePreviewUrl: r.pagePreviewUrl })
})
if (!n) throw new Error('No page could be extracted: ' + JSON.stringify(failed))
return [{ json: { pages, failed, files: n }, binary, pairedItem: { item: 0 } }]

// Each page with its whole-page link (every section assembled, with a Download HTML button).
const saved = $('Save Each Page as Files').first().json
return saved.pages.map(p => ({ json: p, pairedItem: { item: 0 } }))
  .concat(saved.failed.map(f => ({ json: { url: f.url, failed: true, error: f.error }, pairedItem: { item: 0 } })))
